function formatNRC(raw) {
    const digits = (raw || "").replace(/\D/g, "").slice(0, 9);
    let out = digits.slice(0, 6);
    if (digits.length > 6) out += "/" + digits.slice(6, 8);
    if (digits.length > 8) out += "/" + digits.slice(8, 9);
    return out;
}
