async function saveDB(db) {
    MDB = db;
    const failures = [];
    async function tryUpsert(label, table, rows, opts) {
        if (!rows || !rows.length) return;
        try {
            // Safety net: dedupe by conflict key before sending. If the same key
            // appears twice in one batch (e.g. a client-side id collision), Postgres
            // rejects the whole upsert with "ON CONFLICT DO UPDATE command cannot
            // affect row a second time" -- keep the LAST occurrence of each key so
            // a bad duplicate never blocks the rest of that table's save.
            const conflictKey = (opts && opts.onConflict) || "id";
            const seen = new Map();
            for (const row of rows) { seen.set(row[conflictKey], row); }
            const dedupedRows = Array.from(seen.values());
            const { error } = await sb.from(table).upsert(dedupedRows, opts || {});
            if (error) failures.push(`${label}: ${error.message}`);
        } catch (e) {
            failures.push(`${label}: ${e.message || "Unknown error"}`);
        }
    }
    await tryUpsert("Staff", "staff", db.staff?.length ? db.staff.map(staffOut) : null, { onConflict: "id" });
    await tryUpsert("Clients", "clients", db.clients?.length ? db.clients.map(clientOut) : null, { onConflict: "id" });
    await tryUpsert("Loans", "loans", db.loans?.length ? db.loans.map(loanOut) : null, { onConflict: "loan_no" });
    await tryUpsert("Payments", "payments", db.payments?.length ? db.payments.map(paymentOut) : null, { onConflict: "id" });
    await tryUpsert("Leave Requests", "leave_requests", db.leaveRequests?.length ? db.leaveRequests.map(leaveOut) : null, { onConflict: "id" });
    await tryUpsert("Daily Reports", "daily_reports", db.dailyReports?.length ? db.dailyReports.map(dailyReportOut) : null, { onConflict: "id" });
    await tryUpsert("Branch Disbursements", "branch_disbursements", db.branchDisbursements?.length ? db.branchDisbursements.map(d => ({ id: d.id, branch: d.branch, province: d.province, amount: d.amount, category: d.category, note: d.note || null, date: d.date, sent_by: d.sentBy })) : null, { onConflict: "id" });
    await tryUpsert("Payment Plans", "payment_plans", db.paymentPlans?.length ? db.paymentPlans.map(paymentPlanOut) : null, { onConflict: "id" });
    await tryUpsert("Messages", "messages", db.messages?.length ? db.messages.map(messageOut) : null, { onConflict: "id" });
    await tryUpsert("Withdrawal Requests", "withdrawal_requests", db.withdrawalRequests?.length ? db.withdrawalRequests.map(withdrawalOut) : null, { onConflict: "id" });
    await tryUpsert("Money Accounts", "money_accounts", db.moneyAccounts?.length ? db.moneyAccounts.map(moneyAccountOut) : null, { onConflict: "id" });
    await tryUpsert("Money Account Transactions", "money_account_txns", db.moneyAccountTxns?.length ? db.moneyAccountTxns.map(moneyTxnOut) : null, { onConflict: "id" });
    await tryUpsert("M&E Targets", "me_targets", db.meTargets?.length ? db.meTargets.map(t => ({ id: t.id, kpi: t.kpi, scope_type: t.scopeType, scope_value: t.scopeValue || null, target_value: t.targetValue, period: t.period, notes: t.notes || null, created_by: t.createdBy, created_at: t.createdAt })) : null, { onConflict: "id" });
    await tryUpsert("Document Requests", "document_requests", db.documentRequests?.length ? db.documentRequests.map(documentRequestOut) : null, { onConflict: "id" });
    await tryUpsert("Provincial Delegations", "provincial_delegations", db.provincialDelegations?.length ? db.provincialDelegations.map(d => ({ id: d.id, province: d.province, granted_to_staff_id: d.grantedToStaffId, granted_to_name: d.grantedToName, granted_by: d.grantedBy, date_granted: d.dateGranted, active: d.active, note: d.note || null })) : null, { onConflict: "id" });
    const bfRows = Object.entries(db.branchFunds || {}).map(([branch, amount]) => ({ branch, amount }));
    await tryUpsert("Branch Funds", "branch_funds", bfRows.length ? bfRows : null, { onConflict: "branch" });
    const pfRows = Object.entries(db.provincialFunds || {}).map(([province, amount]) => ({ province, amount }));
    await tryUpsert("Provincial Funds", "provincial_funds", pfRows.length ? pfRows : null, { onConflict: "province" });
    const cfIds = new Set([...Object.keys(db.consultantFunds || {}), ...Object.keys(db.consultantTargets || {})]);
    const cfRows = [...cfIds].map(staff_id => ({ staff_id, amount: (db.consultantFunds || {})[staff_id] || 0, target: (db.consultantTargets || {})[staff_id] || 0 }));
    await tryUpsert("Consultant Funds", "consultant_funds", cfRows.length ? cfRows : null, { onConflict: "staff_id" });
    await tryUpsert("Bank Account", "bank_account", [{ id: 1, balance: db.bankBalance || 0 }]);
    if (failures.length) {
        console.error("saveDB errors", failures);
        alert("⚠️ Some data failed to save to the database:\n\n" + failures.join("\n") + "\n\nYour changes may only exist on this device until this is fixed. Please screenshot this and report it.");
    }
    scheduleGoogleBackup(); // fire-and-forget: tells the server to pull fresh data from Supabase and mirror it to Google. Never blocks or throws into the UI.
    return { ok: failures.length === 0, errors: failures };
}

// ── GOOGLE DRIVE / SHEETS AUTO-BACKUP ───────────────────────────────────────
// Debounced so a burst of quick saves (e.g. typing through a form) doesn't
// fire a flood of backup requests — it settles 3s after the last save.
// The server endpoint reads directly from Supabase (source of truth), so
// this call carries no data — it's just a "go back up now" trigger.
let _gBackupTimer = null;
function scheduleGoogleBackup() {
    if (_gBackupTimer) clearTimeout(_gBackupTimer);
    _gBackupTimer = setTimeout(runGoogleBackup, 3000);
}
async function runGoogleBackup() {
    try {
        const res = await fetch("/api/backup-to-drive", { method: "POST" });
        if (!res.ok) console.warn("Google backup failed:", await res.text().catch(() => res.statusText));
    } catch (e) {
        // Deliberately silent to the user — this is a secondary safety net, not the primary save path.
        console.warn("Google backup request failed:", e);
    }
}
async function logLoginToDB(u) {
    try {
        const { data } = await sb.from("login_logs").insert([{ staff_id: u.id, name: u.name, role: u.role, role_label: u.roleLabel, branch: u.branch, province: u.province }]).select("id").single();
        return data?.id || null;
    }
    catch (e) {
        console.error(e);
        return null;
    }
}
async function logLogoutToDB(logId) {
    if (!logId)
        return;
    try {
        await sb.from("login_logs").update({ logged_out_at: new Date().toISOString() }).eq("id", logId);
    }
    catch (e) {
        console.error(e);
    }
}
// ── CALCULATIONS ──────────────────────────────────────────────────────────────
const fmt = n => "K " + Number(n || 0).toLocaleString("en", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const today = () => new Date().toISOString().split("T")[0];
const pad = (n, l = 4) => String(n).padStart(l, "0");
// Base the next client id on the highest existing CLT-#### number, not the
// array's current length -- length breaks after any deletion (reuses an id)
// and can momentarily disagree between devices; max-existing-number doesn't.
function nextClientId(clients) {
    const maxNum = (clients || []).reduce((max, c) => {
        const m = /^CLT-(\d+)$/.exec(c.id || "");
        return m ? Math.max(max, parseInt(m[1], 10)) : max;
    }, 0);
    return `CLT-${pad(maxNum + 1)}`;
}
const validNRC = n => /^\d{6}\/\d{2}\/\d{1}$/.test((n || "").trim());
const isHO = r => HO_ROLES.includes(r);
const isProvincial = r => r === "provincial";
function scopeLoans(db, user) {
    if (isHO(user.role)) return db.loans;
    if (isProvincial(user.role)) return db.loans.filter(l => l.province === user.province);
    return bL(db, user.branch);
}
function scopeClients(db, user) {
    if (isHO(user.role)) return db.clients;
    if (isProvincial(user.role)) return db.clients.filter(c => c.province === user.province);
    return bC(db, user.branch);
}
function scopePayments(db, user) {
    if (isHO(user.role)) return db.payments;
    if (isProvincial(user.role)) { const towns = (PROVINCES[user.province]?.towns || []).map(t => t[0]); return db.payments.filter(p => towns.includes(p.branch)); }
    return bP(db, user.branch);
}
function getBal(loan, pmts) { return Math.max(0, (loan.totalDue || 0) - pmts.filter(p => p.loanNo === loan.loanNo).reduce((s, p) => s + p.amount, 0)); }
function getDOD(loan) { if (!loan.dueDate)
    return 0; const d = Math.floor((new Date() - new Date(loan.dueDate)) / 86400000); return d > 0 ? d : 0; }
function rawTimeStatus(loan) {
    if (!loan.dueDate)
        return "Active";
    const d = Math.floor((new Date() - new Date(loan.dueDate)) / 86400000);
    if (d >= 30)
        return "Defaulted";
    if (d > 0)
        return "Overdue";
    return "Active";
}
function getPen(loan, pmts) { const d = getDOD(loan), b = getBal(loan, pmts); if (!d || !b)
    return 0; return b * 0.05 * Math.min(d, 7); }
function getDI(loan, pmts) { if (rawTimeStatus(loan) !== "Defaulted")
    return 0; return getBal(loan, pmts) * 0.05 * 7; }
function getTotalOwed(loan, pmts) { const bal = getBal(loan, pmts); const rst = rawTimeStatus(loan); if (rst === "Defaulted")
    return bal + getDI(loan, pmts); if (rst === "Overdue")
    return bal + getPen(loan, pmts); return bal; }
function getSt(loan, pmts) {
    if (loan.approvalStatus === "Pending")
        return "Pending";
    if (loan.approvalStatus === "Rejected")
        return "Rejected";
    if (getTotalOwed(loan, pmts) <= 0.005)
        return "Cleared";
    return rawTimeStatus(loan);
}
