                const nd = { ...db, withdrawalRequests: wdl.map(w => w.id === targetId ? { ...w, amount: a, audit: [...(w.audit || []), { action: "Amount edited by Admin", by: user.name, date: today(), note: `Changed to ${fmt(a)}` }] } : w) };
                saveDB(nd); setDb(nd);
